INSERT INTO sep_irm (pseudonyme, date_examen, nb_lesions_t2, cr_irm_texte, localisation_peri_ventriculaire, localisation_juxta_corticale, localisation_sous_tentorielle, localisation_moelle, prise_contraste_gd, nb_lesions_rehaussees, nouvelles_lesions_vs_irm_anterieure, atrophie_cerebrale_medullaire) VALUES ('SEP_AZ_005', '2025-04-04', NULL, 'Hypersignaux T2 FLAIR périventriculaires, juxtaventriculaires, corps calleux, capsule interne gauche, sous-corticaux fronto-temporaux bilatéraux ; 1 black hole sous-cortical insulaire gauche ; prise de contraste nodulaire temporale droite et basifrontale droite ; sous-tentoriel : pédoncule cérébelleux moyen droit et bilatéral, mésencéphale, nodule cérébelleux inférieur droit ; pas d''anomalie orbitaire ni médullaire.', TRUE, TRUE, TRUE, FALSE, TRUE, 2, NULL, FALSE);
INSERT INTO sep_irm (pseudonyme, date_examen, nb_lesions_t2, cr_irm_texte, localisation_peri_ventriculaire, localisation_juxta_corticale, localisation_sous_tentorielle, localisation_moelle, prise_contraste_gd, nb_lesions_rehaussees, nouvelles_lesions_vs_irm_anterieure, atrophie_cerebrale_medullaire) VALUES ('SEP_MBH_003', '2025-04-10', NULL, 'Sous-tentoriel : hypersignaux FLAIR nodulaires pédoncules cérébelleux moyens et pont, pas de black hole. Sus-tentoriel : hypersignaux FLAIR/iso T1 substance blanche sous- et périventriculaire bilatérale, aspect en crête de coq, tronc et corps calleux, bras antérieur capsule interne gauche, sous-cortical fronto-pariétal bilatéral, prise de contraste nodulaire périventriculaire carrefour ventriculaire. Orbitaire : hypersignal T2 nerf optique gauche intra-orbitaire non rehaussé ; lésion graisseuse sous-cutanée toit orbite gauche 14x11x6mm (probable kyste dermoïde, non lié à la SEP). Médullaire : lésions hypersignal T2 cordon antérieur/postérieur/latéral C2-C7/D2-D4, pas de prise de contraste.', TRUE, TRUE, TRUE, TRUE, TRUE, 1, NULL, FALSE);
INSERT INTO sep_irm (pseudonyme, date_examen, nb_lesions_t2, cr_irm_texte, localisation_peri_ventriculaire, localisation_juxta_corticale, localisation_sous_tentorielle, localisation_moelle, prise_contraste_gd, nb_lesions_rehaussees, nouvelles_lesions_vs_irm_anterieure, atrophie_cerebrale_medullaire) VALUES ('SEP_MJ_001', '2026-05-29', NULL, 'Anomalies de signal substance blanche périventriculaire latérale gauche, pédoncule cérébral gauche, pontique et cérébelleux gauche, ovalaires, hypersignal T2 FLAIR, isosignal T1, discret hypersignal diffusion sans restriction ADC ; prise de contraste homogène des lésions périventriculaires et pontiques après gadolinium. Médullaire : sans anomalie.', TRUE, FALSE, TRUE, FALSE, TRUE, NULL, NULL, FALSE);
INSERT INTO sep_irm (pseudonyme, date_examen, nb_lesions_t2, cr_irm_texte, localisation_peri_ventriculaire, localisation_juxta_corticale, localisation_sous_tentorielle, localisation_moelle, prise_contraste_gd, nb_lesions_rehaussees, nouvelles_lesions_vs_irm_anterieure, atrophie_cerebrale_medullaire) VALUES ('SEP_MJ_002', '2023-11-28', NULL, 'Comparativement à l''IRM du 24/04/2023 : nouvelle lésion nodulaire frontale droite hypersignal T2 FLAIR/diffusion avec restriction ADC, rehaussée après gadolinium (8mm) ; lésions ovalaires substance blanche diffuse bilatérale quasi stables, aspect en crête de coq, 2 lésions genou/tronc du corps calleux ; lésion sous-tentorielle pédoncule cérébelleux moyen droit stable. Médullaire : cône terminal normal en D12, sans anomalie à ce stade (atteinte médullaire D11 apparue ultérieurement en 2025).', TRUE, TRUE, TRUE, FALSE, TRUE, 1, TRUE, FALSE);
INSERT INTO sep_irm (pseudonyme, date_examen, nb_lesions_t2, cr_irm_texte, localisation_peri_ventriculaire, localisation_juxta_corticale, localisation_sous_tentorielle, localisation_moelle, prise_contraste_gd, nb_lesions_rehaussees, nouvelles_lesions_vs_irm_anterieure, atrophie_cerebrale_medullaire) VALUES ('SEP_ZM_004', '2025-03-19', NULL, 'Anomalie de signal ovoïde latéro-mésencéphalique gauche rehaussée après gadolinium ; multiples anomalies nodulaires ovoïdes substance blanche périventriculaire sous-corticale fronto-pariétale, certaines en hyposignal (black holes), aspect en crête de coq, non rehaussées après gadolinium. Pas d''anomalie médullaire.', TRUE, TRUE, TRUE, FALSE, TRUE, 1, NULL, FALSE);
INSERT INTO sep_biologie_lcr (pseudonyme, date_prelevement, bandes_oligoclonales, index_chaines_kappa, index_igg, anticorps_type, anticorps_autre_texte) VALUES ('SEP_AZ_005', '2025-04-08', NULL, NULL, NULL, NULL, 'PL faite, cytochimie normale ; anti-AQP4/anti-MOG demandés (résultats non précisés dans le dossier)');
INSERT INTO sep_biologie_lcr (pseudonyme, date_prelevement, bandes_oligoclonales, index_chaines_kappa, index_igg, anticorps_type, anticorps_autre_texte) VALUES ('SEP_MJ_001', '2026-05-30', 'Negatif', NULL, NULL, 'NMO_IgG_MOG', 'Anti-MOG sang/LCR négatifs, anti-AQP4 sang négatif. LCR : 1 élément blanc, glucorachie 3,66 mmol/L, protéinorachie 0,16 g/L, chlorurachie 117 mmol/L (tout normal).');
INSERT INTO sep_biologie_lcr (pseudonyme, date_prelevement, bandes_oligoclonales, index_chaines_kappa, index_igg, anticorps_type, anticorps_autre_texte) VALUES ('SEP_MJ_002', '2025-09-17', NULL, NULL, 2.4, NULL, 'IEPP : index IgG à 2,4 avec synthèse intrathécale. LCR : 8 éléments blancs, glucorachie normale 2,98, protéinorachie discrètement élevée 0,57 g/L, lactorachie normale 1,42.');
INSERT INTO sep_biologie_lcr (pseudonyme, date_prelevement, bandes_oligoclonales, index_chaines_kappa, index_igg, anticorps_type, anticorps_autre_texte) VALUES ('SEP_ZM_004', '2025-03-19', NULL, NULL, NULL, 'NMO_IgG_MOG', 'LCR aspect eau de roche, 8 éléments blancs, protéinorachie 0,42 g/L, glucorachie et chlorurachie normales. Anti-MOG et anti-AQP4 (sang) négatifs le 25/03/2025 ; isoélectrofocalisation LCR en cours.');
